package cn.zhuatech.dealer;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import java.util.regex.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DeepDealerOpsTests{@Autowired MockMvc mvc;
 @Test void onboardingOrderAndRebateFormClosedLoop()throws Exception{long d=activeDealer("DLR-1",100000);authorize(d,100);long o=id(post("/api/dealer-ops/orders",orderBody(d,"SO-1",120,100)).andReturn());admin("/api/admin/dealer-ops/orders/"+o+"/approve","{}").andExpect(jsonPath("$.data.status").value("APPROVED"));post("/api/dealer-ops/orders/"+o+"/fulfill","{}");long r=id(post("/api/dealer-ops/orders/"+o+"/rebates","{\"claimNo\":\"RB-1\",\"claimAmount\":1000}").andReturn());admin("/api/admin/dealer-ops/rebates/"+r+"/settle","{\"approvedAmount\":800}").andExpect(jsonPath("$.data.status").value("SETTLED"));}
 @Test void authorizationPriceAndCreditGatesWork()throws Exception{long d=activeDealer("DLR-2",1000);post("/api/dealer-ops/orders",orderBody(d,"SO-X",120,1)).andExpect(status().isConflict());authorize(d,100);post("/api/dealer-ops/orders",orderBody(d,"SO-LOW",80,1)).andExpect(status().isConflict());post("/api/dealer-ops/orders",orderBody(d,"SO-CREDIT",120,20)).andExpect(status().isConflict());}
 @Test void inactiveDealerCannotAuthorizeAndRebateHasCeiling()throws Exception{long d=dealer("DLR-3");post("/api/dealer-ops/dealers/"+d+"/authorizations",authBody(100)).andExpect(status().isConflict());post("/api/dealer-ops/dealers/"+d+"/submit","{}");admin("/api/admin/dealer-ops/dealers/"+d+"/approve","{\"creditLimit\":50000,\"riskLevel\":\"NORMAL\"}");authorize(d,100);long o=id(post("/api/dealer-ops/orders",orderBody(d,"SO-3",120,10)).andReturn());admin("/api/admin/dealer-ops/orders/"+o+"/approve","{}");post("/api/dealer-ops/orders/"+o+"/fulfill","{}");post("/api/dealer-ops/orders/"+o+"/rebates","{\"claimNo\":\"RB-HIGH\",\"claimAmount\":500}").andExpect(status().isConflict());}
 long dealer(String c)throws Exception{return id(post("/api/dealer-ops/dealers","{\"organizationCode\":\"ZH-SH\",\"dealerCode\":\""+c+"\",\"name\":\"华东渠道伙伴\",\"taxNo\":\"91310000"+c+"\",\"agreementEnd\":\"2027-12-31\"}").andReturn());}long activeDealer(String c,double limit)throws Exception{long d=dealer(c);post("/api/dealer-ops/dealers/"+d+"/submit","{}");admin("/api/admin/dealer-ops/dealers/"+d+"/approve","{\"creditLimit\":"+limit+",\"riskLevel\":\"NORMAL\"}");return d;}void authorize(long d,double min)throws Exception{post("/api/dealer-ops/dealers/"+d+"/authorizations",authBody(min));}String authBody(double min){return "{\"productCode\":\"SKU-100\",\"regionCode\":\"CN-EAST\",\"minimumUnitPrice\":"+min+",\"validFrom\":\"2026-01-01\",\"validTo\":\"2027-12-31\"}";}String orderBody(long d,String n,double u,int q){return "{\"dealerId\":"+d+",\"orderNo\":\""+n+"\",\"productCode\":\"SKU-100\",\"regionCode\":\"CN-EAST\",\"quantity\":"+q+",\"unitPrice\":"+u+",\"orderDate\":\"2026-09-01\"}";}ResultActions post(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content(b));}ResultActions admin(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("admin","admin123")).contentType(MediaType.APPLICATION_JSON).content(b));}long id(MvcResult r)throws Exception{var m=Pattern.compile("\"id\":(\\d+)").matcher(r.getResponse().getContentAsString());Assertions.assertTrue(m.find());return Long.parseLong(m.group(1));}}
